def _typed(path) -> pl.LazyFrame:
    """The stocks CSV with explicit types: dates from their first 10 characters, numbers as floats.
    A value that doesn't parse becomes null, and C6 counts those instead of the run stopping."""
    return pl.scan_csv(path, infer_schema_length=0).with_columns(
